// smoke.spec.js — tool-specific checks for QR Code Reader from Image.
// Fixtures sample-qr.png, sample-wifi.png and sample-two-codes.png are generated by tests/make-fixtures.js (fictional data).
const { test, expect } = require('@playwright/test');
const path = require('path');
const fs = require('fs');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const MENU = 'https://menu.example.org/copper-spoon-bistro/dinner';
const MIME = { png: 'image/png', jpg: 'image/jpeg', pdf: 'application/pdf', heic: 'image/heic' };

// Builds a DataTransfer with real fixture bytes inside the page and fires a drop (or paste) event.
async function sendFiles(page, names, how = 'drop') {
  const files = names.map((name) => ({ name, type: MIME[name.split('.').pop()] || '', b64: fs.readFileSync(fixture(name)).toString('base64') }));
  await page.evaluate(({ files, how }) => {
    const dt = new DataTransfer();
    for (const f of files) {
      const bytes = Uint8Array.from(atob(f.b64), (c) => c.charCodeAt(0));
      dt.items.add(new File([bytes], f.name, { type: f.type }));
    }
    if (how === 'paste') {
      document.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true }));
    } else {
      const zone = document.getElementById('dropzone');
      for (const type of ['dragenter', 'dragover', 'drop']) zone.dispatchEvent(new DragEvent(type, { dataTransfer: dt, bubbles: true, cancelable: true }));
    }
  }, { files, how });
}

test.describe('QR Code Reader from Image', () => {
  test.beforeEach(async ({ page }) => {
    // Never let a test reach the fictional host; a confirmed open is answered locally.
    await page.context().route(/example\.org/, (route) => route.fulfill({ status: 200, contentType: 'text/html', body: '<title>menu</title>' }));
    await page.goto('./');
  });

  test('smoke: dropping sample-qr.png shows the decoded menu link text', async ({ page }) => {
    await sendFiles(page, ['sample-qr.png']);
    const card = page.locator('#results .qr-card');
    await expect(card).toHaveCount(1);
    await expect(card.locator('.qr-text')).toHaveText(MENU);
    await expect(card.locator('.qr-card__type')).toHaveText('Link');
    await expect(card.locator('.qr-link__host')).toHaveText('menu.example.org');
    await expect(page.locator('#results .qr-preview__canvas')).toBeVisible();
  });

  test('smoke: the decoded URL is plain text and is not opened automatically', async ({ page, context }) => {
    let popups = 0;
    page.on('popup', () => popups++);
    const startUrl = page.url();
    await sendFiles(page, ['sample-qr.png']);
    await expect(page.locator('#results .qr-text')).toHaveText(MENU);
    await page.waitForTimeout(500);
    expect(popups).toBe(0);
    expect(context.pages()).toHaveLength(1);
    expect(page.url()).toBe(startUrl);
    // Shown as text, never as a live link or markup.
    await expect(page.locator('#results a')).toHaveCount(0);
    expect(await page.locator('#results .qr-text').evaluate((n) => n.children.length)).toBe(0);
    // "Open link…" only asks; nothing opens until the explicit confirm.
    await page.click('#results .qr-open');
    await expect(page.locator('#results .qr-confirm')).toBeVisible();
    await expect(page.locator('#results .qr-confirm')).toContainText('menu.example.org');
    expect(popups).toBe(0);
    const [popup] = await Promise.all([page.waitForEvent('popup'), page.click('#results .qr-open-confirm')]);
    expect(popup.url()).toBe(MENU);
  });

  test('smoke: an image without a QR code shows a no code found message with tips', async ({ page }) => {
    await sendFiles(page, ['sample.png']);
    const err = page.locator('#results .alert.alert--error');
    await expect(err).toContainText(/No QR code found/i, { timeout: 30_000 });
    await expect(err).toContainText(/crop closer/i);
    await expect(err).toContainText(/glare/i);
    await expect(page.locator('#results .qr-card')).toHaveCount(0);
  });

  test('smoke: the Copy button copies the decoded text (click and Enter)', async ({ page, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);
    await sendFiles(page, ['sample-qr.png']);
    const copy = page.locator('#results .qr-copy');
    await expect(copy).toBeVisible();
    await copy.click();
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(MENU);
    await page.evaluate(() => navigator.clipboard.writeText('cleared'));
    await copy.focus();
    await page.keyboard.press('Enter');
    await expect.poll(() => page.evaluate(() => navigator.clipboard.readText())).toBe(MENU);
  });

  test('smoke: pasting an image from the clipboard also decodes it', async ({ page }) => {
    await sendFiles(page, ['sample-wifi.png'], 'paste');
    const card = page.locator('#results .qr-card');
    await expect(card).toHaveCount(1);
    await expect(card.locator('.qr-card__type')).toHaveText('Wi-Fi network');
    await expect(card.locator('.qr-fields')).toContainText('LanternGuest');
    await expect(card.locator('.qr-fields')).toContainText('WPA');
    // Password is hidden until revealed.
    await expect(card.locator('.qr-secret')).not.toHaveText('paper-lantern-42');
    await card.locator('.qr-reveal').click();
    await expect(card.locator('.qr-secret')).toHaveText('paper-lantern-42');
  });

  test('smoke: works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await expect(page.locator('#dropzone')).toBeInViewport();
    await expect(page.locator('#camera-btn')).toBeVisible();
    await sendFiles(page, ['sample-qr.png']);
    await expect(page.locator('#results .qr-text')).toHaveText(MENU);
    await page.click('#results .qr-open');
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    const box = await page.locator('#results .qr-card').boundingBox();
    expect(box.x).toBeGreaterThanOrEqual(0);
    expect(box.x + box.width).toBeLessThanOrEqual(391);
  });

  test('smoke: several codes in one image are each listed and outlined', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('sample-two-codes.png'));
    const cards = page.locator('#results .qr-card');
    await expect(cards).toHaveCount(2, { timeout: 30_000 });
    const texts = await cards.locator('.qr-text').allTextContents();
    expect(texts.sort()).toEqual([MENU, 'WIFI:T:WPA;S:LanternGuest;P:paper-lantern-42;;'].sort());
  });

  test('smoke: Save text downloads the decoded text as a .txt file', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('sample-qr.png'));
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#results .qr-save-txt')]);
    expect(download.suggestedFilename()).toBe('sample-qr-qr.txt');
    const text = fs.readFileSync(await download.path(), 'utf8');
    expect(text).toBe(MENU);
  });

  test('smoke: wrong file types are rejected even when mixed with a valid image', async ({ page }) => {
    await sendFiles(page, ['sample.pdf', 'sample.heic', 'sample-qr.png']);
    const err = page.locator('#results .alert--error');
    await expect(err).toContainText('sample.pdf');
    await expect(err).toContainText(/not an image/i);
    await expect(err).toContainText(/HEIC/);
    await expect(err).toContainText(/convert/i);
    await expect(page.locator('#results .qr-text')).toHaveText(MENU);
  });

  test('smoke: __demo shows a finished result', async ({ page }) => {
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#results .qr-card')).toHaveCount(2);
  });
});
